export function getExamplesByLetter(letterId: string): LetterExample[] {
  return LETTER_EXAMPLES.filter(ex => ex.letter_id === letterId)
}

export function getExampleById(id: string): LetterExample | undefined {
  return LETTER_EXAMPLES.find(ex => ex.id === id)
}

